This version doesn't rely on logging at all. It collects everything into an object and returns it, so the result shows up as the promise's value. Expand the promise in the console and look at `[[PromiseResult]]`:

```js
// Returns (does not log) IndexedDB names and Firebase token claims.
// Never includes the token itself.
(async () => {
  const out = {};
  try {
    out.databases = (await indexedDB.databases()).map((d) => d.name);
    if (!out.databases.includes("firebaseLocalStorageDb")) return out;
    const db = await new Promise((ok, ko) => {
      const r = indexedDB.open("firebaseLocalStorageDb");
      r.onsuccess = () => ok(r.result);
      r.onerror = () => ko(r.error);
    });
    out.stores = [...db.objectStoreNames];
    const rows = await new Promise((ok, ko) => {
      const r = db
        .transaction("firebaseLocalStorage")
        .objectStore("firebaseLocalStorage")
        .getAll();
      r.onsuccess = () => ok(r.result);
      r.onerror = () => ko(r.error);
    });
    out.entries = rows.map((row) => {
      const jwt = row?.value?.stsTokenManager?.accessToken;
      if (!jwt) return { key: row?.fbase_key, token: false };
      const c = JSON.parse(
        atob(jwt.split(".")[1].replace(/-/g, "+").replace(/_/g, "/")),
      );
      return {
        key: row.fbase_key,
        iss: c.iss,
        aud: c.aud,
        sub: c.sub,
        email: c.email,
        email_verified: c.email_verified,
        exp: new Date(c.exp * 1000).toISOString(),
      };
    });
  } catch (e) {
    out.error = String(e);
  }
  return out;
})();
```

One thing to check about the private window: you need to be signed in to Roam in that window, not just to have the page open. A private window starts with no stored session, so if you haven't signed in there, the Firebase database will be empty or missing, and that's not evidence either way.

